"""Elementary differential equations: a bridge from antiderivatives."""
def make_unit(page,ex,summary):
 return ('Deildajöfnur og upphafsskilyrði',[
 page('Hvað er deildajafna?','Skilja að lausn deildajöfnu er fall.',r'''<p>Í fyrri einingum fundum við stofnföll: föll með tiltekna afleiðu. Nú setjum við sömu spurningu fram sem <strong>deildajöfnu</strong>.</p>\[y'=2x.\]<p>Jafnan segir að afleiða óþekkta fallsins y sé 2x. Við leitum að <strong>falli</strong>, ekki einni tölu.</p><h2>Tvö föll sem uppfylla sömu jöfnu</h2><h3>Sýnidæmi 9.1.1</h3><p>Fallið y=x² hefur afleiðuna:</p>\[y'=2x.\]<p>Það er því lausn jöfnunnar. En fallið y=x²+3 hefur líka afleiðuna:</p>\[y'=2x.\]<p>Bæði föllin eru lausnir. Fastur viðbótarliður hverfur við diffrun, svo fleiri en eitt fall geta uppfyllt sömu deildajöfnu.</p><h2>Jafna með falli og afleiðu</h2><p>Deildajafna er jafna sem inniheldur afleiðu óþekkts falls. Táknin y′ og y″ tákna fyrstu og aðra afleiðu þess. Þegar fallið er gefið með breytunni x má einnig skrifa:</p>\[y'=\frac{dy}{dx}.\]<p>Að <strong>leysa deildajöfnu</strong> er að finna föll sem gera jöfnuna rétta á því bili sem við skoðum.</p>''',[
 ex(r'Er \(y=x^2-5\) lausn jöfnunnar \(y\prime=2x\)?','Finndu afleiðu fallsins.','Afleiða fasta er núll.',r'Já, því \((x^2-5)\prime=2x\).','#s1'),
 ex(r'Er \(y=2x\) lausn jöfnunnar \(y\prime=2x\)?','Berðu afleiðuna saman við hægri hlið jöfnunnar.',r'Afleiða \(2x\) er 2.',r'Nei. Afleiðan er 2, en á að vera 2x á öllu bilinu. Jafna á einum punkti nægir ekki.','#s1'),
 ex(r'Nefndu tvö ólík föll sem uppfylla \(y\prime=3\).','Hvaða föll hafa fastan halla 3?','Byrjaðu á 3x og bættu við föstum.',r'Til dæmis \(y=3x\) og \(y=3x+2\). Bæði hafa afleiðuna 3.','#s1')]),
 page('Lausn athuguð','Athuga lausn með diffrun og innsetningu í upphaflegu jöfnuna.',r'''<p>Þegar fall er gefið getum við athugað hvort það sé lausn án þess að kunna að leysa deildajöfnuna. Við <strong>diffrum fallið</strong> og setjum síðan inn í jöfnuna.</p><h3>Sýnidæmi 9.2.1</h3><p>Er y=x³−2x+4 lausn jöfnunnar hér fyrir neðan?</p>\[y'=3x^2-2.\]<p>Diffrun gefur:</p>\[y'=3x^2-2.\]<p>Afleiðan er nákvæmlega hægri hliðin. Fallið er því lausn fyrir öll raungildi x.</p><h2>Þegar fallið sjálft kemur líka fyrir</h2><h3>Sýnidæmi 9.2.2</h3><p>Athugum hvort y=e⁻²ˣ uppfylli:</p>\[y'+2y=0.\]<p>Fyrst diffrum við:</p>\[y'=-2e^{-2x}.\]<p>Síðan setjum við bæði y′ og y inn vinstra megin:</p>\[y'+2y=-2e^{-2x}+2e^{-2x}=0.\]<p>Fallið uppfyllir jöfnuna. Við lærum að finna lausnir af þessari gerð síðar; hér nægir að geta athugað gefið fall.</p><aside>Að athuga gefna lausn og að finna lausn eru tvö ólík verkefni. Athugunin á að vísa í upphaflegu jöfnuna og gilda á öllu bilinu sem lausnin nær yfir.</aside><div class="formula de-choice"><h2>Hvaða fall er lausn?</h2><p>Veldu fall sem uppfyllir y′ = 2y.</p><div class="activity-options"><button type="button" data-de-choice="0" aria-pressed="false">y = e²ˣ</button><button type="button" data-de-choice="1" aria-pressed="false">y = 2x</button><button type="button" data-de-choice="2" aria-pressed="false">y = x²</button></div><p id="de-feedback" role="status"></p></div>''',[
 ex(r'Athugaðu hvort \(y=\sin x+2\) uppfylli \(y\prime=\cos x\).','Diffraðu gefna fallið.','Fastinn 2 hverfur.',r'Já. Afleiðan er \(\cos x\), eins og jafnan krefst.','#s2'),
 ex(r'Athugaðu hvort \(y=3e^{-x}\) uppfylli \(y\prime+y=0\).','Finndu y′ og settu bæði y′ og y inn.',r'\(y\prime=-3e^{-x}\).',r'Já. \(y\prime+y=-3e^{-x}+3e^{-x}=0\).','#s2'),
 ex(r'Athugaðu hvort \(y=x^2\) uppfylli \(y\prime=y\).','Reiknaðu hvora hlið fyrir sig.',r'Vinstri hliðin verður 2x, hægri hliðin x².',r'Nei. \(2x=x^2\) gildir aðeins þegar x=0 eða x=2, ekki á heilu bili.','#s2')]),
 page('Deildajöfnur á forminu y′ = f(x)','Finna almenna lausn með heildun.',r'''<p>Við notum stofnföllin úr <a href="index.html#s3">einingu 1</a>. Þegar hægri hliðin er þekkt fall af x fæst lausnin með einni heildun:</p>\[y'=f(x).\]\[y=\int f(x)\,dx=F(x)+C.\]<p>Hér er F eitt stofnfall f. <strong>Almenna lausnin</strong> lýsir fjölskyldu lausna og inniheldur frjálsan fasta C.</p><h3>Sýnidæmi 9.3.1</h3>\[y'=6x^2-4x+1.\]<p>Heildum lið fyrir lið:</p>\[y=2x^3-2x^2+x+C.\]<p>Athugun með diffrun gefur aftur 6x²−4x+1.</p><h2>Fjölskylda lausnarferla</h2><p>Fyrir y′=2x er almenna lausnin y=x²+C. Breyting á C færir grafið upp eða niður. Við sama x-gildi hafa allir þessir ferlar sama halla.</p>'''+family_widget(False)+r'''<p>Til dæmis er hallinn 2 við x=1, óháð gildi C. Fastinn breytir fallgildunum en ekki afleiðunni.</p>''',[
 ex(r'Finndu almenna lausn \(y\prime=4x-3\).','Heilda lið fyrir lið.','Mundu heildunarfastann.',r'\(y=2x^2-3x+C\). Diffrun gefur 4x−3.','#s3'),
 ex(r'Finndu almenna lausn \(y\prime=e^x+\cos x\).','Notaðu stofnföll vísisfalls og cosinus.',r'Stofnfall cos x er sin x.',r'\(y=e^x+\sin x+C\). Diffrun gefur eˣ+cos x.','#s3'),
 ex(r'Finndu almenna lausn \(y\prime=1/x\) á bilinu x>0.','Hvaða fall hefur afleiðuna 1/x?','Á jákvæða bilinu má skrifa ln x.',r'\(y=\ln x+C\), fyrir x>0.','#s3')]),
 page('Upphafsskilyrði','Nota gefið fallgildi til að finna tiltekna lausn.',r'''<p>Upphafsskilyrði er gefið fallgildi sem ákvarðar heildunarfastann, eins og í <a href="index.html#s7">einingu 1.7</a>. Við finnum fyrst almennu lausnina og setjum síðan gefna punktinn inn.</p><h3>Sýnidæmi 9.4.1</h3><p>Leyst er:</p>\[y'=2x.\]\[y(1)=4.\]<p>Almenna lausnin er y=x²+C. Skilyrðið segir að ferillinn fari í gegnum (1,4), svo:</p>\[4=1^2+C.\]\[C=3.\]<p>Því er lausnin:</p>\[y=x^2+3.\]<p>Athugum hvort tveggja: afleiðan er 2x og y(1)=1+3=4. Lausnin uppfyllir því bæði deildajöfnuna og upphafsskilyrðið.</p><h2>Einn ferill í gegnum punktinn</h2><p>Hvaða gildi á C lætur ferilinn fara í gegnum (1,4)?</p>'''+family_widget(True),[
 ex(r'Leystu \(y\prime=3x^2\) með skilyrðinu \(y(0)=2\).','Finndu fyrst almenna lausn.','Settu x=0 og y=2 inn í y=x³+C.',r'\(y=x^3+2\). Afleiðan er 3x² og y(0)=2.','#s4'),
 ex(r'Leystu \(y\prime=\cos x\) með skilyrðinu \(y(0)=-1\).','Stofnfall cos x er sin x.','sin 0=0.',r'\(y=\sin x-1\). Afleiðan er cos x og y(0)=−1.','#s4'),
 ex(r'Leystu \(y\prime=2x+1\) með skilyrðinu \(y(2)=0\).','Heilda fyrst; upphafspunkturinn þarf ekki að vera x=0.','Almenna lausnin er y=x²+x+C. Settu x=2 inn.',r'\(0=4+2+C\), svo C=−6. Lausnin er \(y=x^2+x-6\); afleiðan er 2x+1 og y(2)=0.','#s4')]),
 page('Þegar önnur afleiða er gefin','Heilda tvisvar og ákvarða tvo heildunarfasta.',r'''<p>Táknmálið y″ merkir aðra afleiðu y. Ef hún er gefin finnum við fyrst y′ og síðan y. Því þarf <strong>tvær heildanir</strong>.</p><h3>Sýnidæmi 9.5.1</h3>\[y''=6x.\]<p>Fyrri heildun gefur:</p>\[y'=3x^2+C_1.\]<p>Seinni heildun gefur:</p>\[y=x^3+C_1x+C_2.\]<p>Fastinn C₁ er heildaður með öðrum liðum. Stofnfall fasta C₁ er C₁x. Síðan bætist nýr heildunarfasti C₂ við. Tveir frjálsir fastar eru því í almennu lausninni.</p><h2>Tvö upphafsskilyrði</h2><h3>Sýnidæmi 9.5.2</h3><p>Bætum við skilyrðunum:</p>\[y'(0)=2.\]\[y(0)=-1.\]<p>Fyrra skilyrðið er sett inn í formúluna fyrir y′:</p>\[2=3\cdot0^2+C_1.\]\[C_1=2.\]<p>Seinna skilyrðið er sett inn í formúluna fyrir y:</p>\[-1=0^3+2\cdot0+C_2.\]\[C_2=-1.\]<p>Lausnin er:</p>\[y=x^3+2x-1.\]<p>Diffrun tvisvar gefur y″=6x. Einnig eru y′(0)=2 og y(0)=−1, svo bæði skilyrðin standast.</p><h2>Hröðun, hraði og staðsetning</h2><h3>Sýnidæmi 9.5.3</h3><p>Hlutur hreyfist eftir beinni línu. Tíminn t er mældur í sekúndum og staðsetningin s í metrum. Hröðunin er föst, 2 m/s². Við t=0 er hraðinn 3 m/s og staðsetningin 5 m.</p>\[s''(t)=2.\]\[s'(0)=3.\]\[s(0)=5.\]<p>Hraðinn fæst með fyrri heildun og fyrsta skilyrðinu:</p>\[s'(t)=2t+C_1=2t+3.\]<p>Staðsetningin fæst með seinni heildun og seinna skilyrðinu:</p>\[s(t)=t^2+3t+C_2=t^2+3t+5.\]<p>Eftir 2 sekúndur er hluturinn í staðsetningunni s(2)=15 m. Hann hefur færst 10 m frá upphafsstaðnum. Diffrun lausnarinnar gefur hraðann 2t+3 og hröðunina 2, eins og krafist var.</p><aside>Jafna með y″ er annars stigs deildajafna. Hér tökum við aðeins þá einföldu gerð þar sem y″ er gefið sem fall af x; megináherslan í framhaldinu verður á fyrsta stigs jöfnur.</aside>''',[
 ex(r'Finndu almenna lausn \(y\prime\prime=4\).','Heilda tvisvar og gefðu föstunum ólík nöfn.',r'Fyrst fæst y′=4x+C₁.',r'\(y=2x^2+C_1x+C_2\). Tvöföld diffrun gefur 4.','#s5'),
 ex(r'Leystu \(y\prime\prime=6x\), með \(y\prime(0)=1\) og \(y(0)=4\).','Ákvarðaðu fastann í y′ áður en þú notar skilyrðið á y.',r'y′=3x²+C₁, svo C₁=1.',r'\(y=x^3+x+4\). Þá er y′=3x²+1 og y″=6x; bæði upphafsskilyrðin standast.','#s5'),
 ex(r'Leystu \(y\prime\prime=-\sin x\), með \(y\prime(0)=2\) og \(y(0)=0\).','Hvaða fall hefur afleiðuna −sin x?',r'y′=cos x+C₁. Af y′(0)=2 fæst C₁=1.',r'\(y=\sin x+x\). Þá er y′=cos x+1 og y″=−sin x; y′(0)=2 og y(0)=0.','#s5')]),
 page('Samantekt, orðalisti og formúlur','Tengja deildajöfnu, lausn og upphafsskilyrði.',summary([
 'Lausn deildajöfnu er fall sem uppfyllir jöfnuna á viðkomandi bili.','Athuga má gefna lausn með diffrun og innsetningu.','Almenn lausn y′=f(x) fæst með einni heildun og inniheldur einn frjálsan fasta.','Upphafsskilyrði gefur fallgildi sem má nota til að ákvarða fastann.','Ef y″ er gefið þarf að heilda tvisvar og halda utan um tvo fasta.','Tiltekna lausn þarf að athuga bæði í deildajöfnunni og öllum gefnum skilyrðum.'
 ],[
 ('<a href="#s1">Deildajafna</a> <span lang="en">(differential equation)</span>','Jafna sem inniheldur afleiðu óþekkts falls.'),
 ('<a href="#s2">Lausn deildajöfnu</a> <span lang="en">(solution)</span>','Fall sem uppfyllir jöfnuna á tilteknu bili.'),
 ('<a href="#s3">Almenn lausn</a> <span lang="en">(general solution)</span>','Fjölskylda lausna, lýst með frjálsum föstum.'),
 ('<a href="#s3">Lausnarferill</a> <span lang="en">(solution curve)</span>','Graf falls sem er lausn deildajöfnu.'),
 ('<a href="#s4">Upphafsskilyrði</a> <span lang="en">(initial condition)</span>','Gefið gildi falls eða afleiðu þess í tilteknum punkti.'),
 ('<a href="#s4">Tiltekin lausn</a> <span lang="en">(particular solution)</span>','Lausn þar sem frjálsu fastarnir hafa fengið ákveðin gildi.')
 ],r'''<p><strong>Bein heildun þegar fyrsta afleiða er gefin</strong></p>\[y'=f(x).\]\[y=F(x)+C.\]<p>Hér er F′=f á bilinu sem við skoðum. Ef y(x₀)=y₀ fæst:</p>\[C=y_0-F(x_0).\]<p><strong>Tvær heildanir þegar önnur afleiða er gefin</strong></p>\[y''=f(x).\]\[y'=F(x)+C_1.\]\[y=G(x)+C_1x+C_2.\]<p>Hér er F′=f og G′=F. Tvö óháð skilyrði sem ákvarða báða fastana þarf til að velja eina lausn. Fyrir föllin í þessari einingu nægja y(x₀)=y₀ og y′(x₀)=v₀.</p>''')+r'''<h2>Algeng mistök</h2><ul><li>Að gefa tölu sem svar þegar leitað er að falli.</li><li>Að gleyma heildunarfastanum í almennu lausninni.</li><li>Að setja upphafsskilyrði á y inn í formúluna fyrir y′, eða öfugt.</li><li>Að gleyma að C₁ verður C₁x við seinni heildun.</li><li>Að athuga aðeins upphafsskilyrði en ekki deildajöfnuna sjálfa.</li></ul><h2>Athugaðu skilninginn</h2><ul><li>Geturðu sýnt með diffrun að gefið fall sé lausn?</li><li>Geturðu útskýrt hvað C gerir við lausnarferlana fyrir y′=f(x)?</li><li>Geturðu greint hvers vegna tvær heildanir gefa tvo fasta?</li></ul>'''),
 page('Blandað dæmasafn','Velja lausnaleið og athuga niðurstöðu sjálfstætt.','',[
 ex(r'Leystu \(y\prime=3x^2-4\) með \(y(1)=0\).','Finndu almenna lausn og notaðu svo skilyrðið.',r'y=x³−4x+C og 0=1−4+C.',r'\(y=x^3-4x+3\). Afleiðan er 3x²−4 og y(1)=0.','#s4'),
 ex(r'Athugaðu hvort \(y=2e^{3x}\) uppfylli \(y\prime-3y=0\) og \(y(0)=2\).','Ekki þarf að leysa jöfnuna frá grunni; fallið er gefið.',r'y′=6e³ˣ. Settu y′ og y inn í vinstri hliðina.',r'Já. \(y\prime-3y=6e^{3x}-6e^{3x}=0\), og \(y(0)=2\).','#s2'),
 ex(r'Leystu \(y\prime\prime=2\), með \(y\prime(1)=0\) og \(y(1)=3\).','Heilda tvisvar og notaðu hvort skilyrði í viðeigandi formúlu.',r'y′=2x+C₁ gefur C₁=−2. Þá er y=x²−2x+C₂.',r'\(y=x^2-2x+4\). Þá er y″=2, y′(1)=0 og y(1)=3.','#s5'),
 ex(r'Nemandi segir að almenna lausn \(y\prime\prime=6x\) sé \(y=x^3+C\). Er það fullnægjandi?','Athugaðu bæði hvort föllin séu lausnir og hvort allar lausnir hafi verið teknar með.','Hvað gerist við lið á forminu ax þegar diffrað er tvisvar?',r'Föllin eru lausnir, en svarið lýsir ekki öllum lausnum. Almenna lausnin er \(y=x^3+C_1x+C_2\). Liðurinn C₁x hverfur við tvöfalda diffrun.','#s5'),
 ex(r'Hraði hlutar er \(v(t)=4t+1\) m/s. Við t=0 er staðsetning hans 2 m. Finndu staðsetninguna s(t) og færsluna fyrstu 3 sekúndurnar.','Hraði er afleiða staðsetningar. Finndu s og notaðu s(0)=2.',r's(t)=2t²+t+C. Færsla er s(3)−s(0).',r'\(s(t)=2t^2+t+2\). Þá er s(3)=23 m og færslan 23−2=21 m. Athugun: s′(t)=4t+1 og s(0)=2.','#s4'),
 ex(r'Er hægt að ákvarða eina lausn \(y\prime\prime=0\) út frá \(y(0)=3\) einu saman? Rökstyddu.','Skrifaðu almenna lausn áður en þú notar skilyrðið.',r'y′=C₁ og y=C₁x+C₂.',r'Nei. Skilyrðið gefur C₂=3, en C₁ er enn frjáls. Öll föll \(y=C_1x+3\) uppfylla kröfurnar.','#s5'),
 ex(r'Leystu \(y\prime=2/x\) fyrir x>0 með \(y(1)=3\).','Notaðu lograregluna og síðan upphafsskilyrðið.','ln 1=0.',r'\(y=2\ln x+3\), fyrir x>0. Afleiðan er 2/x og y(1)=3.','#s4')])])

def family_widget(initial):
 key='initial' if initial else 'family'
 return f'''<div class="formula de-family" data-initial="{str(initial).lower()}"><svg viewBox="0 0 440 530" style="max-width:440px;display:block;margin:16px auto" role="img" aria-label="Lausnarferlar fyrir y′=2x" data-de-graph></svg><label for="de-{key}"><strong>Heildunarfasti C: <output data-de-value>0</output></strong></label><input id="de-{key}" data-de-slider type="range" min="-3" max="4" step="0.5" value="0" style="display:block;width:100%;margin:20px 0;accent-color:var(--accent)"><p data-de-equation></p><p data-de-status role="status"></p></div>'''
